    ('87d83a5b-d7a2-45dc-b8fd-1bed588bbeec'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Manmodi_Caves', 'https://kevinstandagephotography.wordpress.com/2017/03/18/bhimashankar-caves-junnar/', 'fields-wd1-2026-09-26d-s013-rollback:87d83a5b-d7a2-45dc-b8fd-1bed588bbeec:source_url', 'rollback of fields-wd1-2026-09-26d-s013: source_url ''https://kevinstandagephotography.wordpress.com/2017/03/18/bhimashankar-caves-junnar/'' restored on Bhimashankar Buddhist Caves', '[{"source": "https://en.wikipedia.org/wiki/Manmodi_Caves", "url": "https://en.wikipedia.org/wiki/Manmodi_Caves", "quote": "The Chaitya at Bhimashankar caves, a part of Manmodi Caves, Junnar, India.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Manmodi_Caves", "url": "https://en.wikipedia.org/wiki/Manmodi_Caves", "quote": "Bhimasankar (भीमाशंकर) group, southeast of Manmodi hill, with the inscription of Ayama, minister of Nahapana in 124 CE.", "outcome": "found"}, {"source": "https://www.wondermondo.com/manmod-caves-junnar/", "url": "https://www.wondermondo.com/manmod-caves-junnar/", "quote": "Easternmost is Bhimashankar Group (10 caves), in the middle is Ambika Group (19 caves), and closer to Junnar, more to the north-west is Bhutling Group (16 caves).", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0010)", "decision": "replace", "status": "MISSING", "reasoning": "The stored Kevin Standage blog post refuses automated requests (HTTP 429). The Bhimashankar caves are one of the three groups of the Manmodi Caves south of Junnar; the English Wikipedia article on the Manmodi Caves treats the Bhimasankar group in its own section and shows its chaitya, and Wondermondo independently describes the same Bhimashankar Group, so the Wikipedia article is the best readable page for the site.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Manmodi Caves", "unreadable": false, "wikibase_item": "Q42873620"}}]'::jsonb),
    ('87dcefc2-025d-458b-9418-16e4bac7d17f'::uuid, 'period_name', '500 BC - 1 AD', '3000 - 1500 BC', 'fields-wd1-2026-09-26d-s013-rollback:87dcefc2-025d-458b-9418-16e4bac7d17f:period_name', 'rollback of fields-wd1-2026-09-26d-s013: period_name ''3000 - 1500 BC'' restored on Hod Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
